def scan_test_data_symlinks() -> None:
    global symlink_test_dir1, symlink_test_dir2, symlink_file1, symlink_file2, symlink_file3
    tmpdir1 = list(Path('.').glob('test cases/**/*install functions and follow symlinks'))
