def _dependency_name(package_name: str, api: str, suffix: str = '-rs') -> str:
    return f'{package_name}-{api}{suffix}'


def _parse_git_url(url: str, revision: T.Optional[str] = None) -> T.Tuple[str, str, str]:
    """Return the fetch URL, checkout revision, and subproject name."""
    if url.startswith('git+'):
        url = url[4:]
    parsed = urllib.parse.urlsplit(url)
    query = urllib.parse.parse_qs(parsed.query)
    checkout = (parsed.fragment or revision or
                next((query[key][0] for key in ('rev', 'tag', 'branch')
                      if query.get(key)), 'HEAD'))
    fetch_url = urllib.parse.urlunsplit((parsed.scheme, parsed.netloc,
                                        parsed.path, '', ''))
    directory = os.path.basename(parsed.path.rstrip('/'))
    if directory.endswith('.git'):
        directory = directory[:-4]
    if not directory:
        raise MesonException(f'Cannot determine Cargo subproject name from git URL {url!r}')
    return fetch_url, checkout, directory


_CRATES_IO_SOURCES = {
    'registry+https://github.com/rust-lang/crates.io-index',
    'registry+https://index.crates.io/',
    'sparse+https://index.crates.io/',
}


def load_cargo_lock(filename: str, subproject_dir: str) -> T.Optional[CargoLock]:
    """Load a Cargo.lock and create programmatic wraps for remote packages."""
    if not os.path.exists(filename):
        return None

    raw_lock = T.cast('raw.CargoLock', load_toml(filename))
    lock = CargoLock.from_raw(raw_lock)
    for package in lock.package:
        if package.checksum is None and package.source is not None:
            metadata_key = f'checksum {package.name} {package.version} ({package.source})'
            package.checksum = lock.metadata.get(metadata_key)

        if package.source is None:
            continue
        if package.source in _CRATES_IO_SOURCES:
            archive_name = f'{package.name}-{package.version}.tar.gz'
            values = {
                'directory': f'{package.name}-{package.version}',
                'source_url': (f'https://crates.io/api/v1/crates/{package.name}/'
                               f'{package.version}/download'),
                'source_filename': archive_name,
                'method': 'cargo',
            }
            if package.checksum is not None:
                values['source_hash'] = package.checksum
            lock.wraps[package.subproject] = PackageDefinition.from_values(
                package.subproject, subproject_dir, 'file', values)
            continue
        if package.source.startswith('git+'):
            url, revision, directory = _parse_git_url(package.source)
            wrap = lock.wraps.get(directory)
            if wrap is None:
                wrap = PackageDefinition.from_values(directory, subproject_dir, 'git', {
                    'url': url,
                    'revision': revision,
                    'method': 'cargo',
                })
                lock.wraps[directory] = wrap
            wrap.provided_deps[package.subproject.lower()] = None
            continue
        mlog.warning(f'Unsupported Cargo.lock source {package.source!r} for '
                     f'{package.name} {package.version}; dependency will not be wrapped')

    return lock






def _dependency_varname(dep: Dependency) -> str:
    return f'{fixup_meson_varname(dep.package)}_{(dep.api.replace(".", "_"))}_dep'


def _library_name(name: str, api: str, lib_type: Literal['rust', 'c', 'proc-macro'] = 'rust') -> str:
    # Add the API version to the library name to avoid conflicts when multiple
    # versions of the same crate are used. The Ninja backend removed everything
    # after the + to form the crate name.
    if lib_type == 'c':
        return name
    return f'{name}+{api.replace(".", "_")}'
    return f'{name}+{api.replace(".", "_")}'


